// AI-generated write-ups of popular claims collected from the open internet.
// Original short summaries — not copied from a single publisher.

const F = "FALSE";
const T = "TRUE";
const P = "PARTIALLY_TRUE";
const U = "UNCERTAIN";

function pack(category, rows) {
  return rows.map(([title, verdict, explanation]) => ({
    category,
    title,
    verdict,
    explanation,
  }));
}

